params.script:
set -euo pipefail
node --input-type=module - <<'NIGHTLY_JS_EOF'
import { spawnSync, execFileSync } from 'node:child_process';
import { writeFileSync, mkdirSync, openSync, closeSync, readSync, fstatSync, rmSync, existsSync, readdirSync, readFileSync } from 'node:fs';
import { tmpdir, constants as osConstants } from 'node:os';
import { join, resolve } from 'node:path';
const JUNIT_ENTITIES = { quot: '"', apos: "'", lt: '<', gt: '>', amp: '&' };

function junitDecode(s) {
  return s.replace(/&(?:#x([0-9a-fA-F]+)|#(\d+)|(quot|apos|lt|gt|amp));/g, (m, hex, dec, name) => {
    if (name) return JUNIT_ENTITIES[name];
    const cp = hex ? parseInt(hex, 16) : parseInt(dec, 10);
    try {
      return String.fromCodePoint(cp);
    } catch {
      return m;
    }
  });
}

function junitAttrs(raw) {
  const out = {};
  const re = /([^\s=/]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
  let m;
  while ((m = re.exec(raw)) !== null) {
    out[m[1]] = junitDecode(m[2] !== undefined ? m[2] : m[3]);
  }
  return out;
}

function parseJUnit(xml) {
  // Drop comments and CDATA (failure bodies) so their text can't look like tags.
  const clean = xml.replace(/<!--[\s\S]*?-->/g, '').replace(/<!\[CDATA\[[\s\S]*?\]\]>/g, '');
  const tagRe = /<(\/?)(testcase|failure|error|skipped)\b((?:"[^"]*"|'[^']*'|[^>"'])*?)(\/?)>/g;
  const cases = [];
  let cur = null;
  const finish = () => {
    if (!cur) return;
    const classname = cur.classname;
    const id = classname ? `${classname}::${cur.name}` : `${cur.file ?? ''}::${cur.name}`;
    cases.push({ id, name: cur.name, classname, file: cur.file, status: cur.status });
    cur = null;
  };
  let m;
  while ((m = tagRe.exec(clean)) !== null) {
    const [, closing, tag, rawAttrs, selfClose] = m;
    if (tag === 'testcase') {
      if (closing) {
        finish();
      } else {
        finish();
        const a = junitAttrs(rawAttrs);
        cur = { name: a.name ?? '', classname: a.classname ?? '', file: a.file || null, status: 'passed' };
        if (selfClose) finish();
      }
    } else if (cur && !closing) {
      if (tag === 'skipped') {
        if (cur.status !== 'failed') cur.status = 'skipped';
      } else {
        cur.status = 'failed';
      }
    }
  }
  finish();
  return cases;
}

function junitFindXml(dir, acc) {
  const entries = readdirSync(dir, { withFileTypes: true });
  entries.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  for (const e of entries) {
    const p = join(dir, e.name);
    if (e.isDirectory()) junitFindXml(p, acc);
    else if (e.isFile() && e.name.toLowerCase().endsWith('.xml')) acc.push(p);
  }
  return acc;
}

function readJUnitDir(dir) {
  const files = junitFindXml(dir, []);
  if (files.length === 0) throw new Error(`no JUnit XML in ${dir}`);
  const cases = [];
  for (const f of files) cases.push(...parseJUnit(readFileSync(f, 'utf8')));
  return cases;
}

function statusById(cases) {
  const byId = new Map();
  for (const c of cases) {
    const prev = byId.get(c.id);
    if (prev === undefined || c.status === 'failed' || (prev === 'skipped' && c.status === 'passed')) {
      byId.set(c.id, c.status);
    }
  }
  return byId;
}

function summarize(cases) {
  const byId = statusById(cases);
  let skipped = 0;
  const failing = [];
  for (const [id, status] of byId) {
    if (status === 'skipped') skipped++;
    else if (status === 'failed') failing.push(id);
  }
  failing.sort();
  return { total: byId.size, skipped, failing };
}
const EXEC_TAIL = 1048576;

function execTailOfFd(fd) {
  const size = fstatSync(fd).size;
  const len = Math.min(size, EXEC_TAIL);
  const buf = Buffer.alloc(len);
  let off = 0;
  while (off < len) {
    const n = readSync(fd, buf, off, len - off, size - len + off);
    if (n <= 0) break;
    off += n;
  }
  return buf.subarray(0, off).toString('utf8');
}

function sh(cmd, { cwd, env, timeoutMs } = {}) {
  const logPath = join(tmpdir(), `nightly-sh-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2)}.log`);
  const fd = openSync(logPath, 'w+');
  try {
    const r = spawnSync('bash', ['-c', cmd], {
      cwd,
      env: { ...process.env, ...(env || {}) },
      stdio: ['ignore', fd, fd],
      timeout: timeoutMs,
    });
    const out = execTailOfFd(fd);
    let code;
    if (r.error && r.error.code === 'ETIMEDOUT') code = 124;
    else if (r.error) return { code: 127, out: out + String(r.error.message) };
    else if (r.status !== null) code = r.status;
    else code = 128 + (osConstants.signals[r.signal] || 0);
    return { code, out };
  } finally {
    closeSync(fd);
    rmSync(logPath, { force: true });
  }
}

function git(args, cwd) {
  try {
    return execFileSync('git', ['-c', 'core.hooksPath=/dev/null', ...args], {
      cwd,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
      maxBuffer: 256 * 1024 * 1024,
    });
  } catch (e) {
    const stderr = e.stderr ? String(e.stderr) : '';
    throw new Error(`git ${args.join(' ')} failed: ${stderr.trim() || e.message}`);
  }
}

function repoDir(env) {
  const ws = env.AGENT_WORKSPACE_PATH;
  const full = env.REPO_FULL_NAME;
  if (!ws) throw new Error('AGENT_WORKSPACE_PATH is not set');
  if (!full) throw new Error('REPO_FULL_NAME is not set');
  const name = full.split('/')[1];
  if (!name) throw new Error(`REPO_FULL_NAME has no "/": ${full}`);
  const dir = join(ws, name);
  if (!existsSync(join(dir, '.git'))) throw new Error(`repo not found at ${dir}`);
  return dir;
}

function execTail(s) {
  return s.length > EXEC_TAIL ? s.slice(s.length - EXEC_TAIL) : s;
}

function runSuite({ dir, setup, test, junitDir, timeoutMs }) {
  const jd = resolve(junitDir);
  rmSync(jd, { recursive: true, force: true });
  mkdirSync(jd, { recursive: true });
  let log = '';
  let setupCode = 0;
  if (setup && setup.trim()) {
    const s = sh(setup, { cwd: dir, timeoutMs });
    setupCode = s.code;
    log += `== setup\n${s.out}\n`;
    if (setupCode !== 0) return { setupCode, testCode: null, cases: null, log: execTail(log) };
  }
  const t = sh(test, { cwd: dir, env: { NIGHTLY_JUNIT_DIR: jd }, timeoutMs });
  log += `== test\n${t.out}\n`;
  // A killed run's partial XML must never read as a result.
  let cases = null;
  if (t.code !== 124) {
    try {
      cases = readJUnitDir(jd);
    } catch (e) {
      cases = null;
    }
  }
  return { setupCode, testCode: t.code, cases, log: execTail(log) };
}

function outputJson(obj) {
  const f = process.env.OC_OUTPUT_FILE;
  if (f) writeFileSync(f, JSON.stringify(obj));
}
const MARKER_PREFIX = '<!-- nightly-test-failure ';
const MARKER_SUFFIX = ' -->';

// GitHub caps issue bodies at 65536 characters; the marker line alone stays under this.
const MARKER_BUDGET = 60000;

function markerLine(b) {
  const o = {
    sha: b.sha, junit: b.junit, tests: b.tests, allFailing: b.allFailing,
    total: b.total, skipped: b.skipped, setup: b.setup, test: b.test,
    causeCommand: b.causeCommand, greenNights: b.greenNights,
  };
  if (b.allFailingTruncated === true) o.allFailingTruncated = true;
  if (b.testsTruncated === true) o.testsTruncated = true;
  const json = JSON.stringify(o).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
  return MARKER_PREFIX + json + MARKER_SUFFIX;
}

// Over budget: drop allFailing (allFailingTruncated), then keep the longest sorted prefix of
// tests that fits (testsTruncated). Readers treat both flags fail-closed.
function formatMarker(b) {
  let line = markerLine(b);
  if (line.length <= MARKER_BUDGET) return line;
  const noAll = { ...b, allFailing: [], allFailingTruncated: true };
  line = markerLine(noAll);
  if (line.length <= MARKER_BUDGET) return line;
  const sorted = [...b.tests].sort();
  let lo = 0;
  let hi = sorted.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (markerLine({ ...noAll, tests: sorted.slice(0, mid), testsTruncated: true }).length <= MARKER_BUDGET) lo = mid;
    else hi = mid - 1;
  }
  line = markerLine({ ...noAll, tests: sorted.slice(0, lo), testsTruncated: true });
  if (line.length > MARKER_BUDGET) throw new Error(`marker exceeds ${MARKER_BUDGET} characters even without test ids`);
  return line;
}

function markerIsStrArray(a) {
  return Array.isArray(a) && a.every((x) => typeof x === 'string');
}

function markerIsCount(n) {
  return Number.isInteger(n) && n >= 0;
}

function parseMarker(body) {
  if (typeof body !== 'string') return null;
  const found = [...body.matchAll(new RegExp(MARKER_PREFIX.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(.*?)' + MARKER_SUFFIX.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'))];
  if (found.length !== 1) return null;
  let o;
  try { o = JSON.parse(found[0][1]); } catch { return null; }
  if (!o || typeof o !== 'object' || Array.isArray(o)) return null;
  if (typeof o.sha !== 'string' || !/^[0-9a-f]{40}$/i.test(o.sha)) return null;
  if (typeof o.junit !== 'boolean') return null;
  if (!markerIsStrArray(o.tests) || !markerIsStrArray(o.allFailing)) return null;
  if (!markerIsCount(o.total) || !markerIsCount(o.skipped) || !markerIsCount(o.greenNights)) return null;
  if (typeof o.setup !== 'string' || typeof o.test !== 'string' || typeof o.causeCommand !== 'string') return null;
  if ('allFailingTruncated' in o && o.allFailingTruncated !== true) return null;
  if ('testsTruncated' in o && o.testsTruncated !== true) return null;
  const m = {
    sha: o.sha, junit: o.junit, tests: o.tests, allFailing: o.allFailing,
    total: o.total, skipped: o.skipped, setup: o.setup, test: o.test,
    causeCommand: o.causeCommand, greenNights: o.greenNights,
  };
  if (o.allFailingTruncated) m.allFailingTruncated = true;
  if (o.testsTruncated) m.testsTruncated = true;
  return m;
}

// Provenance: only triage+ users (and the nightly run) can label an issue, so the label shows
// the marker came through a trusted path. `raw` is the trigger issue's labels as JSON: an array
// of names or of {name} objects. Anything else is untrusted.
function markerTrustedLabels(raw) {
  let a;
  try { a = JSON.parse(String(raw ?? '')); } catch { return false; }
  if (!Array.isArray(a)) return false;
  return a.some((l) => (typeof l === 'string' ? l : l && typeof l === 'object' ? l.name : null) === 'nightly-test-failure');
}
// Per command (setup, then test), as in the nightly run. Two stay under the step's 7200 s limit.
const RERUN_TIMEOUT_MS = 55 * 60 * 1000;
// Keep the log the agent reads (and may quote in a comment) small.
const RERUN_LOG_MAX = 20000;

function rerunCheckout(deps, dir, sha) {
  try {
    // Fetch only when the clone does not already have the commit.
    let present = true;
    try { deps.git(['cat-file', '-e', `${sha}^{commit}`], dir); } catch { present = false; }
    if (!present) deps.git(['fetch', 'origin', sha], dir);
    deps.git(['checkout', '--detach', sha], dir);
  } catch (e) {
    throw new Error(`cannot check out baseline ${sha}: ${e.message}`);
  }
}

// Split the marker's tests by the rerun. Skipped or absent counts as still failing.
function rerunSplit(tests, cases) {
  const byId = statusById(cases);
  const stillFailing = [];
  const nowPassing = [];
  for (const id of tests) (byId.get(id) === 'passed' ? nowPassing : stillFailing).push(id);
  return { stillFailing, nowPassing };
}

function rerunResult(marker, r) {
  const log = String(r.log || '').slice(-RERUN_LOG_MAX);
  const base = { junit: marker.junit, sha: marker.sha, testCode: r.testCode, log };
  // The marker kept only a prefix of the cause's ids: the rerun judged that prefix only.
  if (marker.testsTruncated) base.testsTruncated = true;
  if (r.setupCode !== 0) {
    return {
      ...base, setupFailed: true, setupCode: r.setupCode,
      stillFailing: marker.junit ? marker.tests : true, nowPassing: marker.junit ? [] : false, cases: null,
    };
  }
  if (!marker.junit) {
    return { ...base, stillFailing: r.testCode !== 0, nowPassing: r.testCode === 0, cases: null };
  }
  const cases = r.cases === undefined ? null : r.cases;
  // Same rule as the nightly run: non-zero exit with no failing case means the XML is incomplete.
  if (cases === null || (r.testCode !== 0 && summarize(cases).failing.length === 0)) {
    return {
      ...base, rerunError: `no per-test results from rerun (exit ${r.testCode})`,
      stillFailing: marker.tests, nowPassing: [], cases: null,
    };
  }
  return { ...base, ...rerunSplit(marker.tests, cases), cases };
}

function rerunSummary(res) {
  const n = (v) => (Array.isArray(v) ? v.length : v);
  const out = { junit: res.junit, stillFailing: n(res.stillFailing), nowPassing: n(res.nowPassing) };
  if (res.rerunError) out.rerunError = res.rerunError;
  if (res.setupFailed) out.setupFailed = true;
  if (res.testsTruncated) out.testsTruncated = true;
  return out;
}

async function main(env, deps = { runSuite, git, outputJson }) {
  if (!markerTrustedLabels(env.ISSUE_LABELS)) throw new Error('issue is not labelled nightly-test-failure');
  const marker = parseMarker(env.ISSUE_BODY);
  if (!marker) throw new Error('no baseline marker in the issue body');
  const stateDir = join(env.AGENT_WORKSPACE_PATH || '', '.nightly');
  const dir = repoDir(env);
  rerunCheckout(deps, dir, marker.sha);

  // Commands come only from the marker: re-run exactly what the nightly run ran.
  const r = deps.runSuite({
    dir,
    setup: marker.setup,
    test: marker.junit ? marker.test : marker.causeCommand,
    junitDir: join(stateDir, 'junit'),
    timeoutMs: RERUN_TIMEOUT_MS,
  });
  const res = rerunResult(marker, r);
  mkdirSync(stateDir, { recursive: true });
  writeFileSync(join(stateDir, 'rerun.json'), JSON.stringify(res, null, 2));
  const summary = rerunSummary(res);
  console.log(`triage rerun at ${marker.sha}: ${JSON.stringify(summary)}`);
  deps.outputJson(summary);
}
await main(process.env);
NIGHTLY_JS_EOF
